export const getGetEntityLabelUrl = (id: string,
    params?: GetEntityLabelParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/labelmaker/entity/${id}?${stringifiedParams}` : `/v1/labelmaker/entity/${id}`
}

